import java.util.List;

record Money(int cents) {
    static final Money NONE = new Money(0);
    static final int WHOLE_PERCENT = 100;
    Money plus(Money that) { return new Money(cents + that.cents); }
    Money minusFloored(Money that) { return new Money(Math.max(cents - that.cents, 0)); }
    Money times(int quantity) { return new Money(cents * quantity); }
    Money percent(int share) { return new Money(cents * share / WHOLE_PERCENT); }
    Money atMost(Money cap) { return exceeds(cap) ? cap : this; }
    boolean exceeds(Money that) { return cents > that.cents; }
}

sealed interface Category permits Meal, Lodging, Mileage, Hospitality {
    Money allowance(Money gross, int quantity);
}
record Meal(Money perPerson) implements Category {
    public Money allowance(Money gross, int quantity) { return gross.atMost(perPerson.times(quantity)); }
}
record Lodging(Money perNight, Money breakfast) implements Category {
    public Money allowance(Money gross, int quantity) {
        Money roomOnly = gross.minusFloored(breakfast.times(quantity));
        return roomOnly.atMost(perNight.times(quantity));
    }
}
record Mileage(Money perKilometre) implements Category {
    static final int FULL_RATE_KILOMETRES = 200;
    static final int REDUCED_PERCENT = 60;
    public Money allowance(Money gross, int quantity) {
        int fullRate = Math.min(quantity, FULL_RATE_KILOMETRES);
        int reducedRate = quantity - fullRate;
        return perKilometre.times(fullRate).plus(perKilometre.percent(REDUCED_PERCENT).times(reducedRate));
    }
}
record Hospitality() implements Category {
    static final int DEDUCTIBLE_PERCENT = 70;
    public Money allowance(Money gross, int quantity) { return gross.percent(DEDUCTIBLE_PERCENT); }
}

record Receipt(Category category, Money gross, int quantity, int ageDays) {
    static final int MAX_AGE_DAYS = 90;
    boolean isExpired() { return ageDays > MAX_AGE_DAYS; }
    Money refund() { return isExpired() ? Money.NONE : category.allowance(gross, quantity); }
}

sealed interface ClaimStatus permits Draft, Submitted, Approved, Rejected {
    default boolean isSettled() { return this instanceof Approved || this instanceof Rejected; }
}
record Draft() implements ClaimStatus {}
record Submitted(String claimant, int submittedOn) implements ClaimStatus {
    static final int REVIEW_DAYS = 14;
    boolean isOverdue(int today) { return today - submittedOn > REVIEW_DAYS; }
