sealed interface Authority permits TeamLead, Director {
    boolean covers(Money total);
}
record TeamLead(Money signingLimit) implements Authority {
    public boolean covers(Money total) { return !total.exceeds(signingLimit); }
}
record Director() implements Authority {
    public boolean covers(Money total) { return true; }
}

record Claim(String claimant, List<Receipt> receipts, Money advance) {
    Money reimbursable() { return receipts.stream().map(Receipt::refund).reduce(Money.NONE, Money::plus); }
    Money payout() { return reimbursable().minusFloored(advance); }
    boolean isWorthFiling() { return reimbursable().exceeds(Money.NONE); }
}

final class ApprovalDesk {
    static ClaimStatus submit(ClaimStatus status, Claim claim, int today) {
        return status instanceof Draft && claim.isWorthFiling() ? new Submitted(claim.claimant(), today) : status;
    }
    static boolean isEligible(Submitted submitted, Claim claim, String approver, Authority authority) {
        return !submitted.claimant().equals(approver) && authority.covers(claim.reimbursable());
    }
    static ClaimStatus approve(ClaimStatus status, Claim claim, String approver, Authority authority, int today) {
        return switch (status) {
            case Submitted submitted when isEligible(submitted, claim, approver, authority) -> new Approved(approver, today);
            default -> status;
        };
    }
    static ClaimStatus reject(ClaimStatus status, String reason) {
        return status instanceof Submitted ? new Rejected(reason) : status;
    }
    static Money payable(ClaimStatus status, Claim claim) {
        return status instanceof Approved ? claim.payout() : Money.NONE;
    }
}

