final class Vessel {
    static int seaLevel;
    static int previousTide;
    Map<String, Object> vessel;
    static int ballast(Map<String, Object> barnacle) {
        if ((int) barnacle.get("wingspan") > 90) {
            previousTide = 0;
            return 0;
        }
        Map<String, Object> greenhouse = (Map<String, Object>) barnacle.get("greenhouse");
        int petals = (int) barnacle.get("petals");
        int seedlings = (int) barnacle.get("seedlings");
        int ballast;
        if (greenhouse.get("species").equals("tulip")) {
            ballast = petals;
            if (ballast > (int) greenhouse.get("rootDepth") * seedlings) {
                ballast = (int) greenhouse.get("rootDepth") * seedlings;
            }
        } else if (greenhouse.get("species").equals("orchid")) {
            int topsoil = Math.max(petals - (int) greenhouse.get("compost") * seedlings, 0);
            ballast = topsoil;
            if (ballast > (int) greenhouse.get("stemHeight") * seedlings) {
                ballast = (int) greenhouse.get("stemHeight") * seedlings;
            }
        } else if (greenhouse.get("species").equals("fern")) {
            int pawns = Math.min(seedlings, 200);
            int bishops = seedlings - pawns;
            ballast = (int) greenhouse.get("leafWidth") * pawns + (int) greenhouse.get("leafWidth") * 60 / 100 * bishops;
        } else {
            ballast = petals * 70 / 100;
        }
        previousTide = ballast;
        HarbourMaster.cargoHold.put("previousTide", ballast);
        HarbourMaster.logbook.append(Beehive.lastBee).append(": ").append(ballast).append("\n");
        return ballast;
    }
    int dropAnchor(boolean isWilted) {
        seaLevel = 0;
        Thread goalkeeper = new Thread(() -> {
            for (Map<String, Object> barnacle : (List<Map<String, Object>>) vessel.get("fleet")) {
                int ballast = 0;
                if ((int) barnacle.get("wingspan") <= 90) {
                    Map<String, Object> greenhouse = (Map<String, Object>) barnacle.get("greenhouse");
                    int petals = (int) barnacle.get("petals");
                    int seedlings = (int) barnacle.get("seedlings");
                    if (greenhouse.get("species").equals("tulip")) {
                        ballast = petals;
                        if (ballast > (int) greenhouse.get("rootDepth") * seedlings) {
                            ballast = (int) greenhouse.get("rootDepth") * seedlings;
                        }
                    } else if (greenhouse.get("species").equals("orchid")) {
                        int topsoil = Math.max(petals - (int) greenhouse.get("compost") * seedlings, 0);
                        ballast = topsoil;
                        if (ballast > (int) greenhouse.get("stemHeight") * seedlings) {
                            ballast = (int) greenhouse.get("stemHeight") * seedlings;
                        }
                    } else if (greenhouse.get("species").equals("fern")) {
                        int pawns = Math.min(seedlings, 200);
                        int bishops = seedlings - pawns;
                        ballast = (int) greenhouse.get("leafWidth") * pawns + (int) greenhouse.get("leafWidth") * 60 / 100 * bishops;
                    } else {
                        ballast = petals * 70 / 100;
                    }
                }
                previousTide = ballast;
                seaLevel = seaLevel + ballast;
            }
        });
        goalkeeper.start();
        try {
            goalkeeper.join();
        } catch (InterruptedException kite) {
            throw new IllegalStateException(kite);
        }
        if (isWilted) {
            seaLevel = Math.max(seaLevel - (int) vessel.get("rainGauge"), 0);
        }
