import java.util.List;

record Price(int cents) {
    static final int WHOLE_PERCENT = 100;
    Price plus(Price extra) { return new Price(cents + extra.cents); }
    Price times(int quantity) { return new Price(cents * quantity); }
    Price reducedBy(int percent) { return new Price(cents - cents * percent / WHOLE_PERCENT); }
    Price surchargedBy(int percent) { return new Price(cents + cents * percent / WHOLE_PERCENT); }
    Price roundedUp(int step) { return new Price((cents + step - 1) / step * step); }
    Price atMost(Price cap) { return cents > cap.cents ? cap : this; }
}

record Allotment(int capacity, int sold, int reserved) {
    static final int FULL_HOUSE = 100;
    int free() { return capacity - sold - reserved; }
    int occupancy() { return (sold + reserved) * FULL_HOUSE / capacity; }
    boolean covers(int seats) { return seats <= free(); }
    Allotment withSold(int seats) { return new Allotment(capacity, sold + seats, reserved); }
    Allotment released(int seats) { return new Allotment(capacity, sold, Math.max(reserved - seats, 0)); }
}

sealed interface SaleStatus permits Announced, OnSale, SoldOut, Cancelled {
    default boolean isSelling() { return this instanceof OnSale; }
}
record Announced(int opensOn) implements SaleStatus {}
record OnSale(int openedOn) implements SaleStatus {}
record SoldOut(int closedOn) implements SaleStatus {}
record Cancelled(String reason) implements SaleStatus {}

sealed interface Category permits Standing, Seated, Lounge {
    Price listed(Price base);
}
record Standing() implements Category { public Price listed(Price base) { return base; } }
record Seated(int row) implements Category {
    static final int FRONT_ROWS = 10;
    static final int CENTS_PER_ROW = 120;
    public Price listed(Price base) { return base.plus(new Price(CENTS_PER_ROW).times(Math.max(FRONT_ROWS - row, 0))); }
}
record Lounge(int vouchers) implements Category {
    static final int LOUNGE_PERCENT = 80;
    static final int CENTS_PER_VOUCHER = 450;
    public Price listed(Price base) { return base.surchargedBy(LOUNGE_PERCENT).plus(new Price(CENTS_PER_VOUCHER).times(vouchers)); }
}

sealed interface PriceRule permits EarlyBird, Demand {
    Price adjusted(Price listPrice, Allotment allotment, int daysAhead);
