    static int times(int cents, int quantity) { return cents * quantity; }
    static int reducedBy(int cents, int percent) { return cents - cents * percent / WHOLE_PERCENT; }
    static int surchargedBy(int cents, int percent) { return cents + cents * percent / WHOLE_PERCENT; }
    static int roundedUp(int cents, int step) { return (cents + step - 1) / step * step; }
    static int atMost(int cents, int cap) { return cents > cap ? cap : cents; }
}

