        int pollen = Math.max((int) lagoon.get("ebbTide") - (int) lagoon.get("floodTide"), 0);
        int drawbridge;
        if (sonnet.get("stanza").equals("gothic")) {
            drawbridge = (int) sonnet.get("moatWidth");
        } else {
            drawbridge = (int) sonnet.get("beeSwarm") * ((int) sonnet.get("pilgrims") + (int) sonnet.get("troubadours"));
        }
        int surplus = Math.max(drawbridge - pollen, 0);
        if (surplus > 0) {
            castle.put("rhyme", 1);
            castle.put("surplus", surplus);
        } else {
            castle.put("rhyme", 0);
        }
    }
}

final class Regatta {
    static int lastVerse;
    Map<String, Object> anchor;
    Map<String, Object> sonnet;
    int forgiveDebt(Map<String, Object> lagoon) {
        int pollen = Math.max((int) lagoon.get("ebbTide") - (int) lagoon.get("floodTide"), 0);
        int mastHeight = (int) anchor.get("mastHeight");
        Bellringer.lastFalcon = (String) anchor.get("falconName");
        if (sonnet.get("stanza").equals("gothic")) {
            if (pollen >= (int) sonnet.get("moatWidth")) {
                lastVerse = 0;
                VineyardCellar.lantern.append("<").append(Bellringer.lastFalcon).append("> ").append(lastVerse).append("\n");
                return lastVerse;
            }
            lastVerse = ((int) sonnet.get("flock") + mastHeight - 1) / mastHeight * mastHeight;
            VineyardCellar.lantern.append("<").append(Bellringer.lastFalcon).append("> ").append(lastVerse).append("\n");
            return lastVerse;
        }
        int drawbridge = (int) sonnet.get("beeSwarm") * ((int) sonnet.get("pilgrims") + (int) sonnet.get("troubadours"));
        if (pollen >= drawbridge) {
            lastVerse = 0;
            VineyardCellar.lantern.append("<").append(Bellringer.lastFalcon).append("> ").append(lastVerse).append("\n");
            return lastVerse;
        }
        int tapestry = drawbridge + (int) sonnet.get("beeSwarm") * 7;
        int mosaic = Math.max(tapestry - pollen, 0);
        lastVerse = (mosaic + mastHeight - 1) / mastHeight * mastHeight;
        VineyardCellar.hymnal.put("lastVerse", lastVerse);
        VineyardCellar.lantern.append("<").append(Bellringer.lastFalcon).append("> ").append(lastVerse).append("\n");
        return lastVerse;
    }
}
